import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Get overdue invoices sorted by days overdue (most overdue first).
 * @param {Array} invoices
 * @param {string} asOf
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get VAT summary by rate for issued, partially paid, or paid invoices.
 * @param {Array} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const summary = {};

  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const rate = line.vatRate;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVat(line);

        if (!summary[rate]) {
          summary[rate] = { rate, base: 0, vat: 0 };
        }

        summary[rate].base += base;
        summary[rate].vat += vat;
      });
    });

  return Object.values(summary).sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an overdue invoice.
 * Late fee is 0.04% per day of the amount still owed.
 * @param {{ dueDate: string }} invoice
 * @param {string} asOf
 * @returns {number}
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) return 0;

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const fee = due * daysOverdue * 0.0004;

  return roundCents(fee);
}

