test('vatSummary with single line 21% VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = vatSummary([issued]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  const lineTotal = 85000;
  const tierDiscount = 4250;
  const amountAfterBase = lineTotal - tierDiscount;
  const bulkDiscount = Math.round(amountAfterBase * 0.025);
  const base = lineTotal - tierDiscount - bulkDiscount;
  assert.equal(result[0].base, base);
  const expectedVat = Math.round(base * 21 / 100);
  assert.equal(result[0].vat, expectedVat);
});

